# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import random as _rnd
import pandas as pd
from typing import Dict, List

_SA_SEED = 20240601


def _w(u, v, d):
    """Safe edge weight: missing/None cost gets a large penalty."""
    c = d.get("cost")
    return c if c is not None else 1e9


def _emit(bc, dst, path, G, nparts):
    """Record one path for every partition of dst."""
    for i in range(len(path) - 1):
        s, t = path[i], path[i + 1]
        for j in range(nparts):
            bc.append_dst_partition_path(dst, j, [s, t, G[s][t]])


def _tree_cost(paths, h):
    """Total cost of the union of edges across all paths (edge reuse = free)."""
    used = set()
    total = 0.0
    for p in paths:
        for i in range(len(p) - 1):
            e = (p[i], p[i + 1])
            if e not in used:
                used.add(e)
                total += _w(e[0], e[1], h[e[0]][e[1]])
    return total


def _path_cost(p, h):
    """Cost of a single path's edges."""
    return sum(_w(p[i], p[i + 1], h[p[i]][p[i + 1]])
               for i in range(len(p) - 1))


def _edge_counts(paths):
    """Multiset of directed-edge usage counts across all chosen paths."""
    counts = {}
    for p in paths:
        for i in range(len(p) - 1):
            e = (p[i], p[i + 1])
            counts[e] = counts.get(e, 0) + 1
    return counts


def _obj(counts, h):
    """Evaluator proxy: union edge cost + congestion penalty (load/tp)^2."""
    total = 0.0
    for e, n in counts.items():
        d = h[e[0]][e[1]]
        total += _w(e[0], e[1], d)
        tp = d.get("throughput") or 1.0
        total += 0.005 * (n / tp) ** 2
    return total


def _candidate_pool(h, src, dst, spaths, k=8, budget_mult=3.0):
    """Diverse candidate paths for dst: shortest path + top-k simple paths.

    Always returns at least the shortest path when dst is reachable; every
    enumeration is guarded so this can never raise.
    """
    pool = []
    base = spaths.get(dst)
    if base is not None:
        pool.append(base)
    try:
        limit = (budget_mult * _path_cost(base, h)) if base is not None else 1e12
        for count, p in enumerate(nx.shortest_simple_paths(h, src, dst, weight=_w)):
            if count >= k:
                break
            if p in pool:
                continue
            if _path_cost(p, h) > limit:
                break
            pool.append(p)
    except (nx.NetworkXNoPath, nx.NodeNotFound, Exception):
        pass
    return pool


def _anneal(src, valid, h, chosen, spaths, iters=1500, t0=3.0, alpha=0.995):
    """Simulated annealing over per-destination path choices.

    Solution = index into each dst's candidate pool. Objective is union
    edge cost plus congestion. Moves flip one dst to another candidate;
    counts are updated incrementally in O(path length). Seeded with the
    incumbent solution so it never regresses. Returns None on any problem.
    """
    try:
        rng = _rnd.Random(_SA_SEED)
        pools, dsts = [], []
        for d in valid:
            pool = _candidate_pool(h, src, d, spaths)
            if not pool:
                return None
            pools.append(pool)
            dsts.append(d)
        if not dsts:
            return None

        # seed: match incumbent paths when present, else first candidate
        cur = []
        for j, pool in enumerate(pools):
            idx = 0
            for i, p in enumerate(pool):
                if chosen.get(dsts[j]) == p:
                    idx = i
                    break
            cur.append(idx)
        cur_counts = _edge_counts([pools[i][cur[i]] for i in range(len(dsts))])
        cur_obj = _obj(cur_counts, h)
        best, best_obj = cur[:], cur_obj

        temp = t0
        for _ in range(iters):
            temp *= alpha
            i = rng.randrange(len(dsts))
            pool = pools[i]
            if len(pool) < 2:
                continue
            new_idx = rng.randrange(len(pool))
            if new_idx == cur[i]:
                continue
            old_p, new_p = pool[cur[i]], pool[new_idx]
            # incremental count update
            for k in range(len(old_p) - 1):
                e = (old_p[k], old_p[k + 1])
                cur_counts[e] -= 1
                if cur_counts[e] == 0:
                    del cur_counts[e]
            for k in range(len(new_p) - 1):
                e = (new_p[k], new_p[k + 1])
                cur_counts[e] = cur_counts.get(e, 0) + 1
            new_obj = _obj(cur_counts, h)
            delta = new_obj - cur_obj
            if delta <= 0 or rng.random() < pow(2.718281828, -delta / max(temp, 1e-9)):
                cur[i] = new_idx
                cur_obj = new_obj
                if new_obj < best_obj:
                    best, best_obj = cur[:], new_obj
            else:
                # revert counts
                for k in range(len(new_p) - 1):
                    e = (new_p[k], new_p[k + 1])
                    cur_counts[e] -= 1
                    if cur_counts[e] == 0:
                        del cur_counts[e]
                for k in range(len(old_p) - 1):
                    e = (old_p[k], old_p[k + 1])
                    cur_counts[e] = cur_counts.get(e, 0) + 1
        return {dsts[i]: pools[i][best[i]] for i in range(len(dsts))}
    except Exception:
        return None


def search_algorithm(src, dsts, G, num_partitions):
    """Greedy marginal-cost Steiner broadcast with Steiner-MST fallback.

    Process destinations in order of increasing shortest-path cost; for each,
    examine several candidate simple paths and pick the one minimizing the
    cost of *new* edges only (edges already on the shared trunk are free).
    This greedily builds a shared delivery tree. Independently build a
    Kou-Markowsky Steiner tree and emit whichever yields a cheaper union
    of edges, so the result is never worse than either strategy alone.
    """
    if src not in G:
        return BroadCastTopology(src, dsts, num_partitions)
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    valid = [d for d in dict.fromkeys(dsts) if d in h]
    try:
        dist, spaths = nx.single_source_dijkstra(h, src, weight=_w)
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        dist, spaths = {}, {}

    # --- Strategy A: greedy marginal-cost routing, multiple orderings ---
    import random as _rnd

    def _greedy_run(order):
        paths, used = {}, set()
        for dst in order:
            best_path, best_marg = spaths.get(dst), float("inf")
            if best_path is not None:
                best_marg = sum(_w(best_path[i], best_path[i + 1],
                                   h[best_path[i]][best_path[i + 1]])
                                for i in range(len(best_path) - 1)
                                if (best_path[i], best_path[i + 1]) not in used)
            try:
                gen = nx.shortest_simple_paths(h, src, dst, weight=_w)
                budget = dist.get(dst, float("inf")) * 2 + 1e9
                for count, p in enumerate(gen):
                    if count >= 80 or _tree_cost([p], h) > budget:
                        break
                    marg = sum(_w(p[i], p[i + 1], h[p[i]][p[i + 1]])
                               for i in range(len(p) - 1)
                               if (p[i], p[i + 1]) not in used)
                    if marg < best_marg:
                        best_path, best_marg = p, marg
                    if marg == 0:
                        break
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                pass
            if best_path is None:
                continue
            paths[dst] = best_path
            for i in range(len(best_path) - 1):
                used.add((best_path[i], best_path[i + 1]))
        return paths

    reachable = [d for d in valid if d in spaths]
    orders = [
        sorted(reachable, key=lambda d: dist.get(d, float("inf"))),
        sorted(reachable, key=lambda d: -dist.get(d, float("inf"))),
    ]
    if len(reachable) > 2:
        for _ in range(3):
            o = reachable[:]
            _rnd.shuffle(o)
            orders.append(o)
    greedy_paths = min((_greedy_run(o) for o in orders),
                       key=lambda ps: _tree_cost(list(ps.values()), h))
    plain_paths = {d: spaths[d] for d in reachable}
    if set(greedy_paths) != set(reachable):
        greedy_paths = plain_paths

    # --- Strategy B: Kou-Markowsky Steiner tree on metric closure ---
    steiner_paths = {}
    terminals = [src] + valid
    try:
        dist_paths = dict(nx.all_pairs_dijkstra(h, weight=_w))
        closure = nx.Graph()
        for i, a in enumerate(terminals):
            for b in terminals[i + 1:]:
                if b in dist_paths[a][0]:
                    closure.add_edge(a, b, weight=dist_paths[a][0][b])
        mst = nx.minimum_spanning_tree(closure, weight="weight")
        shared = nx.DiGraph()
        for a, b in mst.edges():
            pa = dist_paths[a][1].get(b)
            pb = dist_paths[b][1].get(a)
            if pa is not None and (pb is None or dist_paths[a][0][b] <= dist_paths[b][0][a]):
                path = pa
            elif pb is not None:
                path = pb
            else:
                continue
            for i in range(len(path) - 1):
                s, t = path[i], path[i + 1]
                shared.add_edge(s, t, cost=_w(s, t, h[s][t]))
        for dst in valid:
            if dst in shared:
                try:
                    steiner_paths[dst] = nx.dijkstra_path(shared, src, dst, weight=_w)
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    pass
        if set(steiner_paths) != set(greedy_paths):
            steiner_paths = {}
    except (nx.NetworkXNoPath, nx.NodeNotFound, KeyError):
        steiner_paths = {}

    cand = [greedy_paths, plain_paths]
    if steiner_paths and set(steiner_paths) == set(greedy_paths):
        cand.append(steiner_paths)
    chosen = min(cand, key=lambda ps: _tree_cost(list(ps.values()), h))

    # --- Strategy C: simulated annealing over per-dst candidate pools ---
    try:
        sa_paths = _anneal(src, valid, h, chosen, spaths)
        if sa_paths is not None and set(sa_paths) == set(chosen):
            cand.append(sa_paths)
            chosen = min(cand, key=lambda ps: _tree_cost(list(ps.values()), h))
    except Exception:
        pass

    for dst in valid:
        path = chosen.get(dst) or spaths.get(dst)
        if path is None:
            continue
        _emit(bc_topology, dst, path, G, bc_topology.num_partitions)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

